// ============================================================
// config.js — Reads all configuration from config.xlsx.
// DO NOT edit this file each release; edit config.xlsx instead.
// Run create_config_xlsx.js once to generate config.xlsx.
//
// Override logic (applies to every tab):
//   "Overridden Value" column non-empty → use it
//   "Overridden Value" column blank     → fall back to "Default Value"
//
// Multi-app: when RPB_APP_DIR env var is set, config.xlsx is read
// from that directory (not __dirname/..). This lets Classic, Connector,
// Enrollment and PIK share these scripts with their own config.xlsx.
// ============================================================

const path = require('path');
const fs   = require('fs');

// If RPB_APP_DIR is set by the IDP server (for non-Payor apps), use it;
// otherwise fall back to the Payor directory (scripts/../).
const APP_DIR = process.env.RPB_APP_DIR
  ? path.resolve(process.env.RPB_APP_DIR)
  : path.join(__dirname, '..');

const CONFIG_XLSX = path.join(APP_DIR, 'config.xlsx');

// Project data (projects.xlsx, <app>/projects, <app>/output, <app>/logs) lives in <DWB>\Projects\WorkFlows\Remote_Regression_Jenkins_IT_Failure
const DATA_BASE = (() => {
  let root = process.env.DWB_PROJECTS ? path.resolve(process.env.DWB_PROJECTS) : null;
  if (!root) {
    let d = __dirname;
    while (path.basename(d).toLowerCase() !== 'developerworkbench' && path.dirname(d) !== d) d = path.dirname(d);
    root = path.basename(d).toLowerCase() === 'developerworkbench' ? path.join(path.dirname(d), 'Projects') : path.join(require('os').homedir(), 'DWB', 'Projects');
  }
  return path.join(root, 'WorkFlows', 'Remote_Regression_Jenkins_IT_Failure');
})();
const DATA_APP = path.join(DATA_BASE, path.basename(APP_DIR));
fs.mkdirSync(DATA_APP, { recursive: true });

if (!fs.existsSync(CONFIG_XLSX)) {
  console.error('ERROR: config.xlsx not found at', CONFIG_XLSX);
  console.error('Run:  node create_config_xlsx.js  to generate it.');
  process.exit(1);
}

// Bootstrap xlsx before we know the configured nodeModules path
const XLSX = (() => {
  const candidates = [
    '' + require('os').homedir().replace(/\\/g, '/') + '/node_modules/xlsx',
    path.join(__dirname, '..', '..', '..', '..', '..', 'node_modules', 'xlsx'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return require(c);
  }
  return require('xlsx');
})();

// Return Overridden Value if non-empty, else Default Value
function resolve(defaultVal, overriddenVal) {
  const ov = (overriddenVal !== undefined && overriddenVal !== null)
    ? String(overriddenVal).trim()
    : '';
  return ov !== '' ? ov : String(defaultVal !== undefined && defaultVal !== null ? defaultVal : '').trim();
}

// General tab: columns are Key | Default Value | Overridden Value | Description
function parseGeneral(ws) {
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1 });
  const map = {};
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row[0]) continue;
    map[String(row[0]).trim()] = resolve(row[1], row[2]);
  }
  return map;
}

// JenkinsJobs tab: ValueStream | Default Email | Overridden Email
function parseJobEmails(ws) {
  if (!ws) return {};
  const rows   = XLSX.utils.sheet_to_json(ws, { header: 1 });
  const emails = {};
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row[0]) continue;
    emails[String(row[0]).trim()] = resolve(row[1], row[2]);
  }
  return emails;
}

// Look up VM details (host, user, password) from vms.xlsx by vm name
function readVmDetails(vmName) {
  const vmsPath = path.join(__dirname, '..', '..', '..', '..', '..', 'vms.xlsx');
  const fallback = { host: '', user: 'weblogic', password: 'weblogic', auth: 'password', sshKey: '' };
  if (!vmName || !fs.existsSync(vmsPath)) return fallback;
  try {
    const vWb  = XLSX.readFile(vmsPath);
    const vWs  = vWb.Sheets[vWb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(vWs, { header: 1 });
    // columns: name, ip, description (= SSH user), password, assigned_to
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      if (row && String(row[0] || '').trim().toLowerCase() === vmName.toLowerCase()) {
        return {
          host:     String(row[1] || '').trim(),
          user:     String(row[2] || '').trim(),
          password: String(row[3] || '').trim(),
          auth:     'password',
          sshKey:   '',
        };
      }
    }
  } catch (e) { /* ignore */ }
  return fallback;
}

const wb = XLSX.readFile(CONFIG_XLSX);

const general    = parseGeneral(wb.Sheets['General']);
const emails     = parseJobEmails(wb.Sheets['JenkinsJobs']);
const monitoring = wb.Sheets['Monitoring'] ? parseGeneral(wb.Sheets['Monitoring']) : {};

// App identity — used for filenames and display
const appName    = general['appName']    || 'Payor';
const srcDirCmd  = general['srcDirCmd']  || 'tosrc';
const srcDirEnv  = general['srcDirEnv']  || 'SRCDIR';

// Read baseline and GP URL from the latest per-project xlsx
function findLatestProjectXlsx() {
  const projectsXlsx = path.join(DATA_BASE, 'projects.xlsx');
  const projDir      = path.join(DATA_APP, 'projects');
  if (!fs.existsSync(projectsXlsx) || !fs.existsSync(projDir)) return { xlsxPath: null, pid: null };
  // RPB_PID env var lets the IDP target a specific project when spawning scripts
  const targetPid = process.env.RPB_PID ? parseInt(process.env.RPB_PID, 10) : NaN;
  try {
    const pWb   = XLSX.readFile(projectsXlsx);
    const pWs   = pWb.Sheets[appName] || pWb.Sheets[pWb.SheetNames[0]];
    const rows  = XLSX.utils.sheet_to_json(pWs, { header: 1 });
    let maxPid  = -1, version = '';
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      if (!row || !row[0]) continue;
      const pid = parseInt(row[0], 10);
      if (isNaN(pid)) continue;
      if (!isNaN(targetPid)) {
        if (pid === targetPid) { maxPid = pid; version = String(row[1] || '').trim(); break; }
      } else {
        if (pid > maxPid) { maxPid = pid; version = String(row[1] || '').trim(); }
      }
    }
    if (maxPid < 0) return { xlsxPath: null, pid: null };
    const match = fs.readdirSync(projDir).find(f => f.startsWith(`${maxPid}_`) && f.endsWith('.xlsx'));
    return { xlsxPath: match ? path.join(projDir, match) : null, pid: maxPid };
  } catch (e) { return { xlsxPath: null, pid: null }; }
}

function readProjectUrls(xlsxPath) {
  const result = { baselineJobs: {}, regressionJobs: {}, gpUrl: '', gpEnabled: false, vmName: '', version: '', baselineVersion: '' };
  if (!xlsxPath || !fs.existsSync(xlsxPath)) return result;
  try {
    const pWb = XLSX.readFile(xlsxPath);
    if (pWb.Sheets['baseline_urls']) {
      const rows = XLSX.utils.sheet_to_json(pWb.Sheets['baseline_urls'], { header: 1 });
      for (let i = 1; i < rows.length; i++) {
        const row = rows[i];
        if (row && row[0]) result.baselineJobs[String(row[0]).trim()] = String(row[1] || '').trim();
      }
    }
    if (pWb.Sheets['regression_urls']) {
      const rows = XLSX.utils.sheet_to_json(pWb.Sheets['regression_urls'], { header: 1 });
      for (let i = 1; i < rows.length; i++) {
        const row = rows[i];
        const vs  = row && row[0] ? String(row[0]).trim() : '';
        const url = row && row[1] ? String(row[1]).trim() : '';
        if (vs && url) {
          if (!result.regressionJobs[vs]) result.regressionJobs[vs] = [];
          result.regressionJobs[vs].push(url);
        }
      }
    }
    if (pWb.Sheets['gp_urls']) {
      const rows = XLSX.utils.sheet_to_json(pWb.Sheets['gp_urls'], { header: 1 });
      for (let i = 1; i < rows.length; i++) {
        const row = rows[i];
        const k = row && row[0] ? String(row[0]).trim() : '';
        const v = row && row[1] ? String(row[1]).trim() : '';
        if (k === 'gp_url')  result.gpUrl    = v;
        if (k === 'enabled') result.gpEnabled = v.toLowerCase() === 'true';
      }
    }
    if (pWb.Sheets['remote_server']) {
      const rows = XLSX.utils.sheet_to_json(pWb.Sheets['remote_server'], { header: 1 });
      for (let i = 1; i < rows.length; i++) {
        const row = rows[i];
        const key = row && row[0] ? String(row[0]).trim() : '';
        const val = row && row[1] ? String(row[1]).trim() : '';
        if (key === 'vm_name')          result.vmName          = val;
        if (key === 'version')           result.version          = val;
        if (key === 'baseline_version')  result.baselineVersion  = val;
      }
    }
  } catch (e) { /* ignore */ }
  return result;
}

const { xlsxPath: _projXlsx, pid: _pid } = findLatestProjectXlsx();
const _projUrls      = readProjectUrls(_projXlsx);
const baselineJobs   = _projUrls.baselineJobs;
const regressionJobs = _projUrls.regressionJobs;
const _gpUrl         = _projUrls.gpUrl;
const _gpEnabled     = _projUrls.gpEnabled || false;
const _vmDetails     = readVmDetails(_projUrls.vmName);

const nodeModules = general['nodeModules'] || '' + require('os').homedir().replace(/\\/g, '/') + '/node_modules';

module.exports = {
  pid:         _pid != null ? _pid : null,
  version:     _projUrls.version     || '',
  testTimeout: parseInt(general['testTimeout'] || '600', 10) || 600,

  appName,
  srcDirCmd,
  srcDirEnv,

  jenkinsJobs:  regressionJobs,
  jobEmails:    emails,
  baselineJobs,

  remote: {
    host:     _vmDetails.host,
    user:     _vmDetails.user,
    password: _vmDetails.password,
    auth:     _vmDetails.auth,
    sshKey:   _vmDetails.sshKey,
  },

  gpServer: {
    url:     _gpUrl,
    enabled: _gpEnabled,
  },

  monitoring: {
    intervalMinutes:  parseInt(monitoring['intervalMinutes']  || '5',  10) || 5,
    heartbeatSeconds: parseInt(monitoring['heartbeatSeconds'] || '60', 10) || 60,
  },

  paths: (() => {
    const baselineVersion = _projUrls.baselineVersion || '';
    const regVersion      = _projUrls.version || '';
    const pid             = _pid != null ? _pid : '0';
    const baselineFile    = `Baseline_${appName}_IT_Status_${pid}_${regVersion}.xlsx`;
    return {
      nodeModules,
      dataAppDir:      DATA_APP,
      outputDir:       general['outputDir']      || null,
      outputFileName:  general['outputFileName'] || '',
      baselineDir:     general['baselineDir']    || path.join(APP_DIR, 'baseline'),
      baselineVersion,
      baselineFile,
      emailFormat:     general['emailFormat']    || path.join(APP_DIR, 'email_format', 'Regression_Email_Format.docx'),
    };
  })(),
};
